using Godot;
using System;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class TimelineCanvasOperations
{
    private static double ClampDelta(double value,double minimum,double maximum)=>value<minimum?minimum:value>maximum?maximum:value;
    public void update_drag(Control owner,double pointer,bool bypass)
    {
        owner.Set("_pointer_x",pointer);owner.Set("_bypass_snap",bypass);double target=Math.Max(0,time_at(owner,pointer)-N(owner,"_drag_offset"));if(owner.Get("snap_enabled").AsBool()&&!bypass)target=Mathf.Snapped(target,.1);string id=owner.Get("drag_id").AsString(),mode=owner.Get("drag_mode").AsString();var originals=owner.Get("_drag_originals").AsGodotDictionary();var primary=originals.GetValueOrDefault(id,new Settings()).AsGodotDictionary();if(primary.Count==0)return;var ids=List(owner,"_drag_ids");if(owner.Get("magnet_enabled").AsBool()&&!bypass){var moving=new GArray();foreach(var item in originals.Values){var state=item.AsGodotDictionary();if(mode!="right")moving.Add(state["start"]);if(mode!="left")moving.Add(state["start"].AsDouble()+state["duration"].AsDouble());}double origin=primary["start"].AsDouble()+(mode=="right"?primary["duration"].AsDouble():0);target=origin+magnetic_delta(owner,target-origin,moving,ids,new GArray(),false,true);}var previews=owner.Get("_preview_states").AsGodotDictionary();previews.Clear();if(mode=="left"){double delta=target-primary["start"].AsDouble();var bounds=trim_delta_bounds(owner,true);delta=ClampDelta(delta,bounds.X,bounds.Y);foreach(var key in ids){var state=originals[key].AsGodotDictionary();var clip=Clips(owner)[_timeline.index_of(Model(owner),key.AsString())].As<Resource>();previews[key]=new Settings{["start"]=state["start"].AsDouble()+delta,["duration"]=state["duration"].AsDouble()-delta,["layer"]=state["layer"],["offset"]=state["offset"].AsDouble()+delta*clip.Get("playback_speed").AsDouble()};}}else if(mode=="right"){double delta=target-primary["start"].AsDouble()-primary["duration"].AsDouble();var bounds=trim_delta_bounds(owner,false);delta=ClampDelta(delta,bounds.X,bounds.Y);foreach(var key in ids){var state=originals[key].AsGodotDictionary();previews[key]=new Settings{["start"]=state["start"],["duration"]=state["duration"].AsDouble()+delta,["layer"]=state["layer"],["offset"]=state["offset"]};}}else{int layerDelta=owner.Get("preview_layer").AsInt32()-primary["layer"].AsInt32(),minimum=-primary["layer"].AsInt32();foreach(var key in ids)minimum=Math.Max(minimum,-originals[key].AsGodotDictionary()["layer"].AsInt32());layerDelta=Math.Max(layerDelta,minimum);double delta=_timeline.nearest_free_group_delta(Model(owner),ids,target-primary["start"].AsDouble(),layerDelta);foreach(var key in ids){var state=originals[key].AsGodotDictionary();previews[key]=new Settings{["start"]=state["start"].AsDouble()+delta,["duration"]=state["duration"],["layer"]=state["layer"].AsInt32()+layerDelta,["offset"]=state["offset"]};}}var preview=previews[id].AsGodotDictionary();owner.Set("preview_time",preview["start"]);owner.Set("preview_duration",preview["duration"]);owner.Set("preview_layer",preview["layer"]);owner.Set("preview_valid",_timeline.can_place_group(Model(owner),previews));owner.EmitSignal("interaction_changed","Esc cancels drag");owner.QueueRedraw();
    }
    public Vector2 trim_delta_bounds(Control owner,bool left)
    {
        double minimum=double.NegativeInfinity,maximum=double.PositiveInfinity;var model=Model(owner);var originals=owner.Get("_drag_originals").AsGodotDictionary();foreach(var key in List(owner,"_drag_ids")){string id=key.AsString();var original=originals[key].AsGodotDictionary();int index=_timeline.index_of(model,id);var clip=Clips(owner)[index].As<Resource>();var actor=_timeline.actor_for_id(model,clip.Get("actor_id").AsString())!;double start=original["start"].AsDouble(),duration=original["duration"].AsDouble(),offset=original["offset"].AsDouble(),speed=clip.Get("playback_speed").AsDouble();if(actor.Get("type_id").AsString() is "audio" or "video" or "video_2d"){if(left)minimum=Math.Max(minimum,-offset/speed);else maximum=Math.Min(maximum,(GD.Load<CSharpScript>("res://scripts/actors/core/ActorAudio.cs").Call("length",actor).AsDouble()-offset)/speed-duration);}if(left){minimum=Math.Max(minimum,-start);maximum=Math.Min(maximum,duration-_timeline.minimum_duration(model,clip));}else minimum=Math.Max(minimum,_timeline.minimum_duration(model,clip)-duration);foreach(var item in _timeline.section_clips(model)){var other=item.As<Resource>();if(!_timeline.actors_obstruct(model,Actors(owner)[index].As<Resource>(),_timeline.actor_for_id(model,other.Get("actor_id").AsString())))continue;if(other.Get("id").AsString()==id||other.Get("layer").AsInt32()!=original["layer"].AsInt32())continue;var otherOriginal=originals.GetValueOrDefault(other.Get("id"),new Settings()).AsGodotDictionary();double otherStart=otherOriginal.GetValueOrDefault("start",other.Get("start_time")).AsDouble(),otherEnd=otherStart+otherOriginal.GetValueOrDefault("duration",other.Get("duration")).AsDouble();if(left&&otherEnd<=start+.000001)minimum=Math.Max(minimum,otherEnd-start);else if(!left&&otherStart>=start+duration-.000001)maximum=Math.Min(maximum,otherStart-start-duration);}}return new Vector2((float)minimum,(float)maximum);
    }
    public void process(Control owner,double delta){var model=owner.Get("model").As<RefCounted>();if(model==null)return;var clips=Clips(owner);var actors=Actors(owner);for(int i=0;i<clips.Count;i++)if(actors[i].As<Resource>().Get("type_id").AsString() is "video" or "video_2d"&&_timeline.clip_is_visible(model,i)){owner.QueueRedraw();break;}var paths=owner.Get("_asset_paths").AsStringArray();if(paths.Length>0&&owner.GetViewport().GuiIsDragging())preview_assets(owner,owner.GetLocalMousePosition(),paths);advance_auto_scroll(owner,delta);}
    public void advance_auto_scroll(Control owner,double delta){if(owner.Get("drag_id").AsString().Length==0)return;double pointer=N(owner,"_pointer_x"),direction=0;if(pointer>owner.Size.X-30)direction=Math.Clamp((pointer-owner.Size.X+30)/30,0,2);else if(pointer<LabelWidth+30)direction=-Math.Clamp((LabelWidth+30-pointer)/30,0,2);if(direction==0)return;owner.EmitSignal("scroll_requested",Math.Max(0,N(owner,"scroll_time")+direction*300*delta/N(owner,"pixels_per_second")));update_drag(owner,pointer,owner.Get("_bypass_snap").AsBool());}
    public void finish_drag(Control owner){owner.EmitSignal("interaction_changed","");string id=owner.Get("drag_id").AsString();owner.Set("drag_id","");if(id.Length>0&&owner.Get("preview_valid").AsBool()){bool plural=List(owner,"_drag_ids").Count>1;string action=owner.Get("drag_mode").AsString()!="move"?(plural?"Trim Actors":"Trim Actor"):(plural?"Move Actors":"Move Actor");_timeline.commit_clip_states(Model(owner),owner.Get("_preview_states").AsGodotDictionary(),action,id);}List(owner,"_drag_ids").Clear();owner.Get("_drag_originals").AsGodotDictionary().Clear();owner.Get("_preview_states").AsGodotDictionary().Clear();owner.QueueRedraw();}
    public void notify_canvas(Control owner,int what){if(what==Node.NotificationDragEnd)clear_asset_drag(owner);if(what==Node.NotificationApplicationFocusOut)cancel_drag(owner);}
}
